  mistakes: mist([['Pausing to check something', 'Berjeda untuk memeriksa sesuatu', 'No pauses; the Lab has no pause button for this reason.', 'Tanpa jeda; Lab tidak punya tombol jeda karena alasan ini.'], ['Repeating mocks to move the score', 'Mengulang simulasi untuk menggerakkan skor', 'Mocks measure; drills move; two weeks between mocks.', 'Simulasi mengukur; latihan menggerakkan; dua minggu antar simulasi.'], ['Reading the percentage first', 'Membaca persentase lebih dulu', 'Grid first; the percentage is one number for three problems.', 'Kisi dulu; persentase adalah satu angka untuk tiga masalah.'], ['Leaving blanks “to be safe”', 'Membiarkan kosong “biar aman”', 'No penalty in this form; answer everything, flag doubts.', 'Tanpa penalti di formulir ini; jawab semua, tandai keraguan.']]),
  glossary: gl([['Mock', 'Simulasi', 'A full practice form under test conditions with a report.', 'Formulir latihan utuh dalam kondisi tes dengan laporan.'], ['Checkpoint', 'Titik periksa', 'A clock time by which a family should be finished.', 'Waktu jam saat satu keluarga seharusnya selesai.'], ['Completion', 'Penyelesaian', 'Attempted items over total items.', 'Soal dikerjakan dibagi total soal.'], ['Estimate if no blanks', 'Estimasi jika tanpa kosong', 'Score plus the expected value of guessing on the blanks.', 'Skor plus nilai harapan menebak pada yang kosong.'], ['Adherence', 'Kepatuhan', 'Sessions done over sessions planned, shown by the tracker.', 'Sesi selesai dibagi sesi direncanakan, ditampilkan pelacak.'], ['Learner tag', 'Tanda pelajar', '“I knew this”, “did not understand”, “ran out of time”.', '“Saya tahu ini”, “belum paham”, “kehabisan waktu”.']]),
